import type { BenchmarkRun } from "../api/contracts";
import { badge, button, h, section } from "../components/dom";
import { empty, errorState, loading } from "../components/states";
import type { Page } from "./page";

export const benchmarksPage: Page = { title: "Benchmarks", feature: "Benchmarks", mount(root, context) {
  const body = h("div", {}, loading("Loading saved benchmark runs…"));
  const render = async () => {
    try {
      const runs = await context.api.get<BenchmarkRun[]>("/benchmarks");
      body.replaceChildren(runs.length ? h("div", { class: "result-list" }, ...runs.map(run => {
        const detail = h("pre", { class: "diagnostic-block hidden" });
        return h("article", { class: "result-card" }, h("div", { class: "card-heading" }, h("strong", {}, run.name), badge(run.variant)),
          h("span", {}, `${new Date(run.modifiedAt).toLocaleString()} · commit ${run.applicationCommit || "working-tree"}`),
          h("pre", { class: "diagnostic-block" }, JSON.stringify(run.summaries, null, 2)),
          button("Open full run", async () => { const value = await context.api.get<unknown>(`/benchmarks/${encodeURIComponent(run.name)}`);
            detail.textContent = JSON.stringify(value, null, 2); detail.classList.remove("hidden"); }, true), detail);
      })) : empty("No benchmark JSON exists under benchmarks/results yet. Use the documented bounded CLI command to create one."));
    } catch (error) { body.replaceChildren(errorState(error, render)); }
  };
  root.replaceChildren(section("Benchmarks", "Compare saved cold/warm latency, retrieval quality, citation validity, tokens, and estimated cost.", body));
  void render(); return () => {};
}};
